(function(){
  const KEY='qrk.global-theme.v1',COOKIE='qrk_global_theme_v1';
  const tokenKeys=['accent','page','surface','text','sidebar','muted','border','icon','badge','badgeText','success','warning','danger'];
  const presets={light:{
    midnight:{name:'Midnight Blue',description:'Dark navy navigation with crisp blue actions.',colors:{accent:'#1683ff',page:'#f7f9fc',surface:'#ffffff',text:'#111827',sidebar:'#111827',muted:'#5f6c7d',border:'#dde4ed',icon:'#eef2f7',badge:'#475569',badgeText:'#ffffff',success:'#247454',warning:'#8a6518',danger:'#aa4034'}},
    charcoal:{name:'Charcoal Teal',description:'Neutral charcoal navigation with QRK cyan.',colors:{accent:'#0fb9c0',page:'#f6f8fa',surface:'#ffffff',text:'#151b25',sidebar:'#171c24',muted:'#596574',border:'#dce2e8',icon:'#edf2f5',badge:'#435263',badgeText:'#ffffff',success:'#237552',warning:'#8b6619',danger:'#ad4036'}},
    slate:{name:'Slate Violet',description:'Cool slate navigation with a restrained violet accent.',colors:{accent:'#7257d9',page:'#f7f7fb',surface:'#ffffff',text:'#181827',sidebar:'#25243a',muted:'#625f72',border:'#e0dfea',icon:'#f0eff7',badge:'#5d5a76',badgeText:'#ffffff',success:'#287252',warning:'#89651c',danger:'#a94345'}},
    forest:{name:'Forest Green',description:'Deep green navigation with calm emerald actions.',colors:{accent:'#117a59',page:'#f5f8f6',surface:'#ffffff',text:'#14211c',sidebar:'#142b24',muted:'#596a62',border:'#d9e3de',icon:'#eaf1ed',badge:'#45655a',badgeText:'#ffffff',success:'#19734f',warning:'#85651d',danger:'#a94138'}}
  },dark:{
    midnight:{name:'Midnight',description:'Deep navy surfaces with bright QRK blue.',colors:{accent:'#4da3ff',page:'#0b1020',surface:'#141b2d',text:'#f3f6fb',sidebar:'#070b14',muted:'#aab5c7',border:'#2b354a',icon:'#202a3e',badge:'#40506a',badgeText:'#ffffff',success:'#54c890',warning:'#e0b64c',danger:'#ee776d'}},
    charcoal:{name:'Carbon',description:'Near-black surfaces with a clear cyan accent.',colors:{accent:'#28c8cf',page:'#0d1117',surface:'#171c23',text:'#f4f6f8',sidebar:'#080b0f',muted:'#abb4c0',border:'#303741',icon:'#222a33',badge:'#465463',badgeText:'#ffffff',success:'#55c991',warning:'#dfb655',danger:'#ef7b71'}},
    dusk:{name:'Dusk Violet',description:'Soft black-violet surfaces with lavender actions.',colors:{accent:'#9b87f5',page:'#100f19',surface:'#1b1927',text:'#f5f3fb',sidebar:'#0b0a11',muted:'#b4afc5',border:'#363247',icon:'#272337',badge:'#554d72',badgeText:'#ffffff',success:'#58c891',warning:'#e0b75a',danger:'#ef7a81'}},
    evergreen:{name:'Evergreen',description:'Dark green-black surfaces with fresh emerald actions.',colors:{accent:'#42c99a',page:'#0b1411',surface:'#14201c',text:'#f0f7f4',sidebar:'#07100d',muted:'#a7bbb3',border:'#2c4038',icon:'#1d3029',badge:'#3f5e53',badgeText:'#ffffff',success:'#55d09a',warning:'#dfb958',danger:'#ef7b72'}}
  }};
  const defaults={mode:'light',lightPreset:'midnight',darkPreset:'midnight',light:{...presets.light.midnight.colors},dark:{...presets.dark.midnight.colors}};
  const valid=value=>/^#[0-9a-f]{6}$/i.test(value||''),clean=(colors,fallback)=>Object.fromEntries(tokenKeys.map(key=>[key,valid(colors?.[key])?colors[key]:fallback[key]]));
  const mix=(hex,amount)=>{const value=parseInt(hex.slice(1),16),target=amount<0?0:255,p=Math.abs(amount),channel=shift=>Math.round(((value>>shift)&255)+(target-((value>>shift)&255))*p);return `#${[16,8,0].map(shift=>channel(shift).toString(16).padStart(2,'0')).join('')}`};
  const luminance=hex=>{const n=parseInt(hex.slice(1),16);return[16,8,0].map(shift=>(n>>shift)&255).map(c=>{c/=255;return c<=.03928?c/12.92:((c+.055)/1.055)**2.4}).reduce((sum,c,index)=>sum+c*[.2126,.7152,.0722][index],0)};
  const contrastText=hex=>{const background=luminance(hex),dark=luminance('#111827'),darkRatio=(background+.05)/(dark+.05),lightRatio=1.05/(background+.05);return darkRatio>=lightRatio?'#111827':'#ffffff'};
  function parseSaved(){try{const cookie=document.cookie.split('; ').find(item=>item.startsWith(`${COOKIE}=`))?.slice(COOKIE.length+1);return JSON.parse(cookie?decodeURIComponent(cookie):localStorage.getItem(KEY)||'{}')}catch{return{}}}
  function normalize(saved={}){if(valid(saved.accent))return{...defaults,lightPreset:'custom',light:clean(saved,defaults.light)};return{mode:saved.mode==='dark'?'dark':'light',lightPreset:saved.lightPreset||'midnight',darkPreset:saved.darkPreset||'midnight',light:clean(saved.light,defaults.light),dark:clean(saved.dark,defaults.dark)}}
  function readState(){return normalize(parseSaved())}
  function read(mode){const state=readState(),resolved=mode==='dark'||mode==='light'?mode:state.mode;return{...state[resolved]}}
  function apply(theme=read(),mode=readState().mode){const root=document.documentElement,accent=theme.accent,dark=mode==='dark';root.dataset.theme=mode;root.style.colorScheme=mode;root.style.setProperty('--brand-400',mix(accent,.18));root.style.setProperty('--brand-500',accent);root.style.setProperty('--brand-600',mix(accent,-.2));root.style.setProperty('--brand-soft',mix(accent,dark?-.72:.9));root.style.setProperty('--brand-ring',`${accent}55`);root.style.setProperty('--brand-foreground',contrastText(accent));root.style.setProperty('--orange',accent);root.style.setProperty('--orange-dark',mix(accent,-.2));root.style.setProperty('--orange-soft',mix(accent,dark?-.72:.9));root.style.setProperty('--paper',theme.page);root.style.setProperty('--surface',theme.surface);root.style.setProperty('--color-white',theme.surface);root.style.setProperty('--ink',theme.text);root.style.setProperty('--gray-900',theme.text);root.style.setProperty('--gray-800',mix(theme.text,dark?-.08:.08));root.style.setProperty('--gray-700',mix(theme.text,dark?-.18:.18));root.style.setProperty('--muted',theme.muted);root.style.setProperty('--gray-500',theme.muted);root.style.setProperty('--gray-600',mix(theme.muted,dark?.1:-.16));root.style.setProperty('--gray-400',mix(theme.muted,dark?-.08:.18));root.style.setProperty('--line',theme.border);root.style.setProperty('--gray-200',theme.border);root.style.setProperty('--gray-300',mix(theme.border,dark?.12:-.08));root.style.setProperty('--surface-muted',theme.icon);root.style.setProperty('--gray-100',theme.icon);root.style.setProperty('--global-badge',theme.badge);root.style.setProperty('--global-badge-text',theme.badgeText);root.style.setProperty('--success',theme.success);root.style.setProperty('--warning',theme.warning);root.style.setProperty('--danger',theme.danger);root.style.setProperty('--nav',theme.sidebar);root.style.setProperty('--global-sidebar',theme.sidebar);root.style.setProperty('--global-sidebar-text',contrastText(theme.sidebar));document.querySelector('meta[name="theme-color"]')?.setAttribute('content',theme.page);return theme}
  function persist(state){const normalized=normalize(state),value=JSON.stringify(normalized);localStorage.setItem(KEY,value);document.cookie=`${COOKIE}=${encodeURIComponent(value)}; Path=/; Max-Age=31536000; SameSite=Lax`;apply(normalized[normalized.mode],normalized.mode);window.dispatchEvent(new CustomEvent('qrk-global-theme-change',{detail:normalized}));return normalized}
  function save(colors,mode=readState().mode,preset='custom'){const state=readState();state[mode]=clean(colors,defaults[mode]);state[`${mode}Preset`]=preset;return persist(state)}
  function setMode(mode){const state=readState();state.mode=mode==='dark'?'dark':'light';return persist(state)}
  function usePreset(mode,id){const preset=presets[mode]?.[id];if(!preset)return readState();const state=readState();state[mode]={...preset.colors};state[`${mode}Preset`]=id;state.mode=mode;return persist(state)}
  function reset(mode=readState().mode){const state=readState();state[mode]={...presets[mode].midnight.colors};state[`${mode}Preset`]='midnight';return persist(state)}
  window.QrkGlobalTheme={defaults,presets,tokenKeys,readState,read,apply,save,setMode,usePreset,reset};
  const initial=readState();apply(initial[initial.mode],initial.mode);
  window.addEventListener('storage',event=>{if(event.key===KEY){const state=readState();apply(state[state.mode],state.mode)}});
  window.addEventListener('focus',()=>{const state=readState();apply(state[state.mode],state.mode)});
  document.addEventListener('visibilitychange',()=>{if(!document.hidden){const state=readState();apply(state[state.mode],state.mode)}});
})();
